import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Force hipcc for ROCm
os.environ.setdefault("CXX", "hipcc")

# A: (M,K=32) float32, B: (K=32,M) float32 -> C: (M,M)
# Custom GEMM specialized for K=32 with 64x64 tiling and 4x4 per thread.

src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>

#ifndef CHECK_HIP
#define CHECK_HIP(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA/HIP tensor")
#endif

__global__ void gemm_k32_64x64_kernel(const float* __restrict__ A,
                                     const float* __restrict__ B,
                                     float* __restrict__ C,
                                     int M) {
    // block computes C tile: [block_y*64 : +64, block_x*64 : +64]
    const int blockRow = (int)blockIdx.y;
    const int blockCol = (int)blockIdx.x;

    const int tidx = (int)threadIdx.x; // 0..15
    const int tidy = (int)threadIdx.y; // 0..15
    const int tid  = tidy * 16 + tidx; // 0..255

    __shared__ float As[64][32]; // 64*32 = 2048 floats
    __shared__ float Bs[32][64]; // 32*64 = 2048 floats

    // Cooperative load A tile (64x32)
    #pragma unroll
    for (int it = 0; it < 8; ++it) {
        int linear = tid + it * 256; // 0..2047
        int r = linear >> 5;         // /32 -> 0..63
        int k = linear & 31;         // %32
        int gr = blockRow * 64 + r;
        float v = 0.0f;
        if (gr < M) {
            v = A[gr * 32 + k];
        }
        As[r][k] = v;
    }

    // Cooperative load B tile (32x64)
    #pragma unroll
    for (int it = 0; it < 8; ++it) {
        int linear = tid + it * 256; // 0..2047
        int k = linear >> 6;         // /64 -> 0..31
        int c = linear & 63;         // %64
        int gc = blockCol * 64 + c;
        float v = 0.0f;
        if (gc < M) {
            v = B[k * (int)M + gc];
        }
        Bs[k][c] = v;
    }

    __syncthreads();

    const int rowBase = blockRow * 64 + tidy * 4;
    const int colBase = blockCol * 64 + tidx * 4;

    float acc00 = 0.f, acc01 = 0.f, acc02 = 0.f, acc03 = 0.f;
    float acc10 = 0.f, acc11 = 0.f, acc12 = 0.f, acc13 = 0.f;
    float acc20 = 0.f, acc21 = 0.f, acc22 = 0.f, acc23 = 0.f;
    float acc30 = 0.f, acc31 = 0.f, acc32 = 0.f, acc33 = 0.f;

    #pragma unroll
    for (int k = 0; k < 32; ++k) {
        float a0 = As[tidy * 4 + 0][k];
        float a1 = As[tidy * 4 + 1][k];
        float a2 = As[tidy * 4 + 2][k];
        float a3 = As[tidy * 4 + 3][k];

        float b0 = Bs[k][tidx * 4 + 0];
        float b1 = Bs[k][tidx * 4 + 1];
        float b2 = Bs[k][tidx * 4 + 2];
        float b3 = Bs[k][tidx * 4 + 3];

        // 4x4 outer product
        acc00 = fmaf(a0, b0, acc00); acc01 = fmaf(a0, b1, acc01); acc02 = fmaf(a0, b2, acc02); acc03 = fmaf(a0, b3, acc03);
        acc10 = fmaf(a1, b0, acc10); acc11 = fmaf(a1, b1, acc11); acc12 = fmaf(a1, b2, acc12); acc13 = fmaf(a1, b3, acc13);
        acc20 = fmaf(a2, b0, acc20); acc21 = fmaf(a2, b1, acc21); acc22 = fmaf(a2, b2, acc22); acc23 = fmaf(a2, b3, acc23);
        acc30 = fmaf(a3, b0, acc30); acc31 = fmaf(a3, b1, acc31); acc32 = fmaf(a3, b2, acc32); acc33 = fmaf(a3, b3, acc33);
    }

    // Store
    if (rowBase + 0 < M && colBase + 0 < M) C[(rowBase + 0) * (int)M + (colBase + 0)] = acc00;
    if (rowBase + 0 < M && colBase + 1 < M) C[(rowBase + 0) * (int)M + (colBase + 1)] = acc01;
    if (rowBase + 0 < M && colBase + 2 < M) C[(rowBase + 0) * (int)M + (colBase + 2)] = acc02;
    if (rowBase + 0 < M && colBase + 3 < M) C[(rowBase + 0) * (int)M + (colBase + 3)] = acc03;

    if (rowBase + 1 < M && colBase + 0 < M) C[(rowBase + 1) * (int)M + (colBase + 0)] = acc10;
    if (rowBase + 1 < M && colBase + 1 < M) C[(rowBase + 1) * (int)M + (colBase + 1)] = acc11;
    if (rowBase + 1 < M && colBase + 2 < M) C[(rowBase + 1) * (int)M + (colBase + 2)] = acc12;
    if (rowBase + 1 < M && colBase + 3 < M) C[(rowBase + 1) * (int)M + (colBase + 3)] = acc13;

    if (rowBase + 2 < M && colBase + 0 < M) C[(rowBase + 2) * (int)M + (colBase + 0)] = acc20;
    if (rowBase + 2 < M && colBase + 1 < M) C[(rowBase + 2) * (int)M + (colBase + 1)] = acc21;
    if (rowBase + 2 < M && colBase + 2 < M) C[(rowBase + 2) * (int)M + (colBase + 2)] = acc22;
    if (rowBase + 2 < M && colBase + 3 < M) C[(rowBase + 2) * (int)M + (colBase + 3)] = acc23;

    if (rowBase + 3 < M && colBase + 0 < M) C[(rowBase + 3) * (int)M + (colBase + 0)] = acc30;
    if (rowBase + 3 < M && colBase + 1 < M) C[(rowBase + 3) * (int)M + (colBase + 1)] = acc31;
    if (rowBase + 3 < M && colBase + 2 < M) C[(rowBase + 3) * (int)M + (colBase + 2)] = acc32;
    if (rowBase + 3 < M && colBase + 3 < M) C[(rowBase + 3) * (int)M + (colBase + 3)] = acc33;
}

torch::Tensor tall_skinny_mm_k32(torch::Tensor A, torch::Tensor B) {
    CHECK_HIP(A);
    CHECK_HIP(B);
    TORCH_CHECK(A.scalar_type() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.scalar_type() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(1) == 32, "This optimized kernel requires K=32 (A.size(1)==32)");
    TORCH_CHECK(B.size(0) == 32, "This optimized kernel requires K=32 (B.size(0)==32)");
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");

    const auto M = (int)A.size(0);
    TORCH_CHECK(B.size(1) == M, "B must have shape (32, M)");

    auto C = torch::empty({M, M}, A.options());

    dim3 block(16, 16, 1);
    dim3 grid((M + 63) / 64, (M + 63) / 64, 1);

    hipLaunchKernelGGL(gemm_k32_64x64_kernel, grid, block, 0, at::hip::getDefaultHIPStream(),
                       (const float*)A.data_ptr<float>(), (const float*)B.data_ptr<float>(), (float*)C.data_ptr<float>(), M);

    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("tall_skinny_mm_k32", &tall_skinny_mm_k32, "Tall-skinny MM K=32 (HIP)");
}
"""

ext = load_inline(
    name="tall_skinny_mm_k32_ext",
    cpp_sources=src,
    functions=None,
    extra_cuda_cflags=["-O3", "-ffast-math"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.ext = ext

    def forward(self, A, B):
        # Ensure on GPU and contiguous; KernelBench will supply CUDA tensors.
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        A = A.contiguous()
        B = B.contiguous()
        # Fall back if K != 32
        if A.shape[1] != 32 or B.shape[0] != 32:
            return torch.matmul(A, B)
        return self.ext.tall_skinny_mm_k32(A, B)

